package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import java.lang.reflect.*;import java.util.*;
/** Local menu interaction checks. No destructive actions, accounts or communication. */
public final class EaseNavigationTests extends Instrumentation {
 int count,chosen=-1,calls,backs;Activity page;KeypadDialog dialog;
 void check(boolean b,String why){if(!b)throw new AssertionError(why);count++;}
 Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 void ui(final Runnable action){final Throwable[] error={null};runOnMainSync(new Runnable(){public void run(){try{action.run();}catch(Throwable t){error[0]=t;}}});if(error[0]!=null)throw new RuntimeException(error[0]);}
 void tap(int key){dialog.onKeyDown(key,new KeyEvent(0,key));dialog.onKeyUp(key,new KeyEvent(1,key));}
 void open(boolean numbers){dialog=new KeypadDialog(page,"Local menu",GlobalMenuModel.labels(false,false),new KeypadDialog.Action(){public void select(int i){chosen=i;calls++;}},numbers);dialog.show();}
 public void onCreate(Bundle b){start();}
 public void onStart(){Bundle out=new Bundle();try{
 int[] root=GlobalMenuModel.actions(false),tools=GlobalMenuModel.actions(true);check(root.length==7,"seven primary actions");check(tools.length==10,"advanced actions retained");Set<Integer> ids=new HashSet<>();for(int id:root)check(ids.add(id)&&!GlobalMenuModel.label(id,false).isEmpty(),"unique root action "+id);for(int id:tools)check(ids.add(id)&&!GlobalMenuModel.label(id,false).isEmpty(),"unique advanced action "+id);check(ids.size()==17,"all actions reachable within two menu levels");root[0]=-1;check(GlobalMenuModel.actions(false)[0]==GlobalMenuModel.HOME,"model cannot be mutated by callers");check(!GlobalMenuModel.label(GlobalMenuModel.POINTER,false).equals(GlobalMenuModel.label(GlobalMenuModel.POINTER,true)),"mouse state label");
 check(Class.forName("com.android.vcard.VCardComposer")!=null&&Class.forName("com.android.vcard.VCardParser_V30")!=null,"contact import/export dependencies present");
 page=startActivitySync(new Intent(getTargetContext(),AndroidControlsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
 ui(new Runnable(){public void run(){open(true);dialog.onKeyDown(KeyEvent.KEYCODE_3,new KeyEvent(0,KeyEvent.KEYCODE_3));dialog.onKeyDown(KeyEvent.KEYCODE_3,new KeyEvent(0,0,0,KeyEvent.KEYCODE_3,1));check(calls==0,"holding does not activate before release");dialog.onKeyUp(KeyEvent.KEYCODE_3,new KeyEvent(1,KeyEvent.KEYCODE_3));check(chosen==2&&calls==1,"digit selects corresponding action");dialog.onKeyUp(KeyEvent.KEYCODE_3,new KeyEvent(1,KeyEvent.KEYCODE_3));check(calls==1,"duplicate release does not activate again");open(true);dialog.onKeyDown(KeyEvent.KEYCODE_4,new KeyEvent(0,KeyEvent.KEYCODE_4));dialog.onKeyUp(KeyEvent.KEYCODE_4,KeyEvent.changeFlags(new KeyEvent(1,KeyEvent.KEYCODE_4),KeyEvent.FLAG_CANCELED));check(calls==1&&dialog.isShowing(),"cancelled key does not activate");dialog.dismiss();open(false);tap(KeyEvent.KEYCODE_2);check(calls==1&&dialog.isShowing(),"ordinary menus keep their original numeric behaviour");dialog.dismiss();open(true);dialog.onBack(new Runnable(){public void run(){backs++;}});tap(KeyEvent.KEYCODE_BACK);check(backs==1&&!dialog.isShowing(),"Back returns to parent");dialog.onKeyUp(KeyEvent.KEYCODE_BACK,new KeyEvent(1,KeyEvent.KEYCODE_BACK));check(backs==1,"parent callback once");open(true);tap(KeyEvent.KEYCODE_DPAD_UP);try{check(((Integer)field(dialog,"selected"))==6,"wrap to last");tap(KeyEvent.KEYCODE_DPAD_DOWN);check(((Integer)field(dialog,"selected"))==0,"wrap to first");}catch(Exception e){throw new RuntimeException(e);}dialog.dismiss();dialog=null;}});
 final MainActivity[] found={null};final boolean[] ready={false};getTargetContext().startActivity(new Intent(getTargetContext(),MainActivity.class).putExtra("open_menu",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));
 for(int n=0;n<50&&found[0]==null;n++){ui(new Runnable(){public void run(){try{Class<?> thread=Class.forName("android.app.ActivityThread");Method current=thread.getDeclaredMethod("currentActivityThread");current.setAccessible(true);Object host=current.invoke(null);Field activities=thread.getDeclaredField("mActivities");activities.setAccessible(true);for(Object record:((Map<?,?>)activities.get(host)).values()){Object activity=field(record,"activity");if(activity instanceof MainActivity&&!((MainActivity)activity).isFinishing()){found[0]=(MainActivity)activity;Object screen=field(found[0],"screen");ready[0]=screen!=null&&(Boolean)field(screen,"grid");}}}catch(Exception e){throw new RuntimeException(e);}}});SystemClock.sleep(100);}
 check(found[0]!=null,"Home activity available");final MainActivity home=found[0];page=home;waitForIdleSync();ui(new Runnable(){public void run(){try{Object screen=field(home,"screen");home.onNewIntent(new Intent(home,MainActivity.class).putExtra("open_menu",true));check((Boolean)field(screen,"grid"),"Apps entry handler opens app menu");home.onNewIntent(new Intent(home,MainActivity.class));check(!(Boolean)field(screen,"grid"),"normal Home entry opens dashboard");home.onNewIntent(new Intent(home,MainActivity.class).putExtra("open_menu",true));check((Boolean)field(screen,"grid"),"existing Apps entry opens app menu");}catch(Exception e){throw new RuntimeException(e);}}});
 out.putString("result","PASS "+count+" local menu and entry checks");
 }catch(Throwable t){out.putString("error",android.util.Log.getStackTraceString(t));}finally{ui(new Runnable(){public void run(){if(dialog!=null)dialog.dismiss();if(page!=null)page.finish();}});}finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
